import sys
sys.path.insert(0, "_tools")
import bl_dispatch
def strings(v):
    if isinstance(v, str):
        yield v
    elif isinstance(v, (list, tuple)):
        for x in v:
            yield from strings(x)
    elif isinstance(v, dict):
        for x in v.values():
            yield from strings(x)
rules = "\n".join(s for name, v in vars(bl_dispatch).items() if not name.startswith("__") for s in strings(v))
worker = open("agents/worker.md", encoding="utf-8").read()
named = "build_index.py" in rules or "build_index.py" in worker
print("worker rules name build_index.py:", named, file=sys.stderr)
sys.exit(0 if named else 1)
